  'ytw-sol': { v: 'tar', d: 'Allongé sur le ventre au sol. Bras tendus décollés du sol en Y au-dessus de la tête, pouces vers le haut.' },
  'rot-ext-poulie': { v: 'f', d: 'Debout de côté à une poulie à hauteur de coude, coude collé au corps et fléchi à 90°. Avant-bras tourné vers l’extérieur.' },
  'rot-ext-halt': { v: 'f', d: 'Allongé sur le côté, coude du dessus collé au corps et fléchi à 90°, haltère léger. Avant-bras tourné vers le plafond.' },
  'rot-int-poulie': { v: 'f', d: 'Debout de côté à une poulie à hauteur de coude, coude collé au corps et fléchi à 90°. Avant-bras tourné vers l’intérieur, vers le ventre.' },

  // ---------- Trapèzes ----------
  'shrug-barre': { v: 'f', d: 'Debout, barre tenue bras tendus devant les cuisses. Épaules haussées vers les oreilles, bras toujours tendus.' },
  'shrug-halteres': { v: 'f', d: 'Debout, un haltère dans chaque main le long du corps. Épaules haussées vers les oreilles.' },
  'shrug-machine': { v: 'f', d: 'Debout dans une machine à shrugs, mains sur les poignées. Épaules haussées vers les oreilles.' },
  'shrug-smith': { v: 'f', d: 'Debout, barre guidée (Smith) tenue devant les cuisses. Épaules haussées vers les oreilles.' },
  'shrug-trapbar': { v: 'f', d: 'Debout à l’intérieur d’une trap bar, poignées sur les côtés, bras tendus. Épaules haussées vers les oreilles.' },
  'shrug-poulie': { v: 'f', d: 'Debout entre deux poulies basses, une poignée dans chaque main. Épaules haussées vers les oreilles.' },
  'shrug-incline': { v: 'tar', d: 'Allongé poitrine contre un banc incliné, haltères bras tendus vers le sol. Omoplates serrées et remontées.' },

  // ---------- Biceps ----------
  'curl-barre': { d: 'Debout, barre droite en supination à largeur d’épaules, coudes collés au corps. Barre montée à mi-course, avant-bras à l’horizontale.' },
  'curl-serre': { d: 'Debout, barre droite en supination, mains rapprochées (10 à 15 cm entre elles), coudes collés au corps. Avant-bras à l’horizontale.' },
  'curl-large': { d: 'Debout, barre droite en supination, mains plus écartées que les épaules, coudes collés au corps. Avant-bras à l’horizontale.' },
  'curl-ez': { d: 'Debout, barre EZ (barre coudée en zigzag) en supination, coudes collés au corps. Avant-bras à l’horizontale.' },
  'curl-halteres': { d: 'Debout, un haltère dans chaque main en supination. Un bras monté (avant-bras à l’horizontale), l’autre en bas.' },
  'curl-simultane': { d: 'Debout, un haltère dans chaque main en supination. Les deux avant-bras montés ensemble à l’horizontale.' },
  'curl-incline': { d: 'Assis sur un banc incliné à 45-60°, dos et tête contre le dossier, bras pendants derrière la ligne du buste, haltères en supination. Avant-bras à l’horizontale, coudes immobiles derrière le buste.' },
  'curl-incline-poulie': { d: 'Allongé sur un banc incliné, dos à une poulie basse, une poignée dans chaque main, câbles qui tirent les bras vers l’arrière. Avant-bras montés, coudes derrière le buste.' },
  'curl-marteau': { d: 'Debout, haltères en prise neutre (pouces vers le haut), coudes collés au corps. Un avant-bras monté à l’horizontale.' },
  'curl-marteau-corde': { d: 'Debout face à une poulie basse, corde tenue en prise neutre, coudes collés. Avant-bras montés à l’horizontale.' },
  'curl-marteau-croise': { v: 'f', d: 'Debout, haltère en prise neutre monté en diagonale devant le corps, vers l’épaule opposée.' },
  'curl-pupitre': { d: 'Assis à un pupitre (Larry Scott), arrière des bras posé sur le coussin incliné, barre EZ en supination. Avant-bras à mi-course.' },
  'curl-pupitre-halt': { d: 'Assis à un pupitre, un seul bras posé sur le coussin, haltère en supination. Avant-bras à mi-course.' },
  'curl-pupitre-machine': { d: 'Assis dans une machine à biceps type pupitre, arrière des bras sur le coussin. Poignées montées à mi-course.' },
  'curl-concentre': { v: 'tav', d: 'Assis sur un banc, buste penché, coude calé contre l’intérieur de la cuisse, haltère en supination. Avant-bras monté vers l’épaule.' },
  'curl-poulie': { d: 'Debout face à une poulie basse, barre droite en supination, coudes collés au corps. Avant-bras à l’horizontale.' },
  'curl-poulie-1bras': { d: 'Debout face à une poulie basse, une poignée dans une main, coude collé au corps. Avant-bras à l’horizontale.' },
  'curl-poulie-haute': { v: 'f', d: 'Debout entre deux poulies hautes, bras écartés à l’horizontale, une poignée dans chaque main. Avant-bras pliés vers les oreilles (pose double biceps).' },
  'curl-bayesian': { d: 'Debout dos à une poulie basse, un pas en avant, bras tiré vers l’arrière par le câble. Avant-bras monté, le coude reste derrière le buste.' },
  'curl-araignee': { d: 'Allongé poitrine contre un banc incliné, bras pendants verticalement devant le banc, haltères en supination. Avant-bras montés à mi-course.' },
  'curl-zottman': { d: 'Debout, coudes collés au corps. Descente : en haut du curl, poignets tournés paumes vers le bas, haltères qui redescendent ainsi.' },
  'curl-drag': { d: 'Debout, barre droite en supination. Barre qui monte en glissant contre le corps, coudes qui partent vers l’arrière, barre au niveau du nombril.' },
  'curl-drag-halt': { d: 'Debout, un haltère dans chaque main en supination. Haltères qui montent en glissant contre le corps, coudes qui partent vers l’arrière.' },
  'curl-21': { d: 'Debout, barre EZ en supination, coudes collés au corps. Barre à mi-course, avant-bras à l’horizontale.' },
  'curl-machine': { d: 'Assis dans une machine à biceps, bras sur l’appui. Poignées montées à mi-course.' },
  'curl-elastique': { d: 'Debout sur un élastique, extrémités tenues en supination, coudes collés au corps. Avant-bras montés à l’horizontale.' },
  'curl-kb': { d: 'Debout, un kettlebell tenu par la poignée en supination, coude collé au corps. Avant-bras à l’horizontale.' },
  'curl-sac': { d: 'Debout, un sac lesté tenu par ses poignées en supination, coudes collés au corps. Avant-bras à l’horizontale.' },

  // ---------- Triceps ----------
