  'barre-front-halt': { d: 'Allongé sur un banc plat, haltères en prise neutre. Avant-bras descendus de chaque côté de la tête, coudes pointés vers le plafond.' },
  'pushdown-barre': { d: 'Debout face à une poulie haute, barre droite en pronation, coudes collés au corps. Avant-bras poussés vers le bas, presque tendus.' },
  'pushdown-corde': { d: 'Debout face à une poulie haute, corde en prise neutre, coudes collés au corps. Bras tendus vers le bas, mains écartées en bas de la corde.' },
  'pushdown-1bras': { d: 'Debout face à une poulie haute, une poignée dans une main, coude collé au corps. Avant-bras poussé vers le bas.' },
  'pushdown-inv': { d: 'Debout face à une poulie haute, barre droite en supination (paumes vers le haut), coudes collés. Avant-bras poussés vers le bas.' },
  'ext-poulie-tete': { d: 'Debout dos à une poulie, buste penché en avant, un pied devant, corde tenue derrière la tête. Bras tendus vers l’avant et le haut, coudes près de la tête.' },
  'ext-halt-tete': { d: 'Assis, un haltère dans une main au-dessus de la tête. Avant-bras descendu derrière la tête, coude pointé vers le plafond.' },
