  'kickback': { d: 'Buste penché à l’horizontale, une main et un genou sur un banc, haltère dans l’autre main, bras collé au corps. Avant-bras tendu vers l’arrière.' },
  'kickback-poulie': { d: 'Buste penché face à une poulie basse, poignée dans une main, bras collé au corps. Avant-bras tendu vers l’arrière.' },
  'dips-triceps': { d: 'En appui sur deux barres parallèles, buste droit, jambes tendues. Bas du mouvement : coudes fléchis à 90°, près du corps.' },
  'dips-banc': { d: 'Mains sur le bord d’un banc derrière soi, jambes tendues devant, talons au sol. Fesses descendues près du sol, coudes fléchis à 90°.' },
  'dips-machine': { d: 'Assis dans une machine à dips, poignées sur les côtés. Poignées poussées vers le bas, bras presque tendus.' },
  'dc-serre': { d: 'Allongé sur un banc plat, barre droite en pronation, mains à largeur d’épaules, coudes près du corps. Barre à mi-course au-dessus de la poitrine.' },
