  'ext-triceps-el': { d: 'Debout face à un élastique fixé en hauteur, coudes collés au corps. Avant-bras poussés vers le bas.' },

  // ---------- Avant-bras ----------
  'wrist-curl': { d: 'Assis, avant-bras posés sur les cuisses, paumes vers le haut, barre dans les mains. Poignets fléchis vers le haut.' },
  'wrist-curl-halt': { d: 'Assis, avant-bras posé sur la cuisse, haltère dans la main paume vers le haut. Poignet fléchi vers le haut.' },
  'reverse-wrist': { d: 'Assis, avant-bras posés sur les cuisses, paumes vers le bas, barre dans les mains. Poignets relevés vers le haut.' },
  'reverse-wrist-halt': { d: 'Assis, avant-bras posé sur la cuisse, haltère dans la main paume vers le bas. Poignet relevé vers le haut.' },
  'wrist-dos': { d: 'Debout, barre tenue derrière le dos, bras tendus, paumes vers l’arrière. Poignets fléchis vers le haut.' },
  'curl-inverse': { d: 'Debout, barre EZ en pronation (paumes vers le bas), coudes collés au corps. Avant-bras à l’horizontale.' },
  'wrist-roller': { d: 'Debout, bras tendus devant soi, mains sur un rouleau à poignets d’où pend une corde avec un petit disque. Poignets qui enroulent la corde.' },
