  'gripper': { d: 'Debout, une main qui serre fort une pince de préhension (hand gripper), bras le long du corps.' },
  'pinch': { d: 'Debout, bras le long du corps, deux disques lisses pincés entre les doigts et le pouce de chaque main.' },
  'pron-sup': { d: 'Assis, avant-bras posé sur la cuisse, haltère tenu par une seule extrémité. Poignet en rotation, pouce vers le haut.' },

  // ---------- Abdos ----------
  'crunch': { d: 'Allongé sur le dos au sol, genoux fléchis, pieds au sol, mains près des tempes. Haut du dos enroulé, épaules décollées du sol.' },
  'crunch-poulie': { d: 'À genoux face à une poulie haute, corde tenue près de la tête. Buste enroulé vers le sol, coudes vers les cuisses.' },
  'crunch-machine': { d: 'Assis dans une machine à abdos, poignées près des épaules. Buste enroulé vers l’avant.' },
  'crunch-inverse': { d: 'Allongé sur le dos, genoux fléchis à 90° en l’air, bras au sol. Bassin enroulé, genoux ramenés vers la poitrine, fesses décollées.' },
