  'rjs': { d: 'Suspendu à une barre fixe, bras tendus. Jambes tendues relevées à l’horizontale.' },
  'rgs': { d: 'Suspendu à une barre fixe, bras tendus. Genoux ramenés vers la poitrine.' },
