  'rj-sol': { d: 'Allongé sur le dos au sol, mains sous les fesses. Jambes tendues relevées à 45°.' },
  'toes-bar': { d: 'Suspendu à une barre fixe. Pieds montés jusqu’à toucher la barre, jambes tendues.' },
  'planche': { d: 'Gainage sur les avant-bras et la pointe des pieds, corps droit de la tête aux talons.' },
  'planche-laterale': { v: 'f', d: 'Gainage sur le côté : appui sur un avant-bras et le côté du pied, corps droit, hanches hautes.' },
  'planche-lestee': { d: 'Gainage sur les avant-bras et la pointe des pieds, un disque posé sur le haut du dos.' },
  'gainage-dyn': { d: 'Gainage : passage d’un appui sur les avant-bras à un appui sur les mains, un bras tendu, l’autre encore sur l’avant-bras.' },
  'hollow': { d: 'Allongé sur le dos, bas du dos plaqué au sol, bras tendus derrière la tête et jambes tendues décollées : corps en forme de banane.' },
  'l-sit': { h: 'les abdominaux et l’avant des hanches', d: 'En appui sur les mains au sol, bras tendus, jambes tendues à l’horizontale devant : corps en L.' },
  'ab-wheel': { d: 'À genoux, mains sur une roue abdominale. Roue roulée loin devant, corps presque à l’horizontale, dos plat.' },
  'rotations-russes': { v: 'tav', d: 'Assis au sol, buste incliné en arrière, pieds décollés, médecine-ball tenu à deux mains. Buste tourné, ballon près de la hanche.' },
  'pallof': { v: 'f', d: 'Debout de côté à une poulie à hauteur de poitrine, poignée tenue à deux mains. Bras tendus devant soi, le buste résiste à la rotation.' },
  'woodchop': { v: 'tav', d: 'Debout de côté à une poulie haute, poignée à deux mains. Mouvement en diagonale vers le bas jusqu’à la hanche opposée, buste en rotation.' },
  'dead-bug': { d: 'Allongé sur le dos, bras tendus vers le plafond, genoux à 90°. Un bras et la jambe opposée tendus vers le sol en même temps.' },
  'mountain': { d: 'En position de pompe bras tendus. Un genou ramené vers la poitrine, l’autre jambe tendue.' },
  'dragon-flag': { d: 'Allongé sur un banc, mains agrippées derrière la tête. Corps tendu en l’air, seuls les épaules et le haut du dos sur le banc.' },
  'v-ups': { d: 'Allongé sur le dos. Bras et jambes tendus qui se rejoignent au-dessus des hanches : corps en V.' },
  'ciseaux': { d: 'Allongé sur le dos, jambes tendues décollées du sol, une plus haute que l’autre (battements).' },
  'flexion-laterale': { v: 'f', d: 'Debout, un haltère dans une main le long du corps. Buste incliné sur le côté vers l’haltère.' },

