  'squat-pause': { d: 'Barre sur le haut du dos, tenue immobile en position basse, cuisses à l’horizontale.' },
  'box-squat': { d: 'Barre sur le haut du dos, fesses posées sur une box derrière soi, tibias verticaux.' },
  'squat-smith': { d: 'Squat sous une barre guidée (Smith), pieds un peu en avant. Cuisses à l’horizontale.' },
  'hack-squat': { d: 'Dos contre le dossier incliné d’une machine hack squat, épaules sous les appuis. Genoux fléchis à 90°.' },
  'hack-barre': { d: 'Barre tenue derrière les jambes, bras tendus. Position basse, cuisses presque à l’horizontale.' },
  'presse': { d: 'Assis dans une presse à cuisses inclinée à 45°, pieds sur la plateforme. Genoux fléchis à 90°.' },
  'presse-horizontale': { d: 'Assis dans une presse horizontale, pieds sur la plateforme. Genoux fléchis à 90°.' },
  'presse-1jambe': { d: 'Presse à cuisses inclinée, un seul pied sur la plateforme. Genou fléchi à 90°.' },
  'pendulum': { d: 'Dans une machine pendulum squat, épaules sous les appuis. Position basse, genoux très fléchis.' },
  'belt-squat': { d: 'Debout sur une machine belt squat, ceinture à la taille reliée à la charge. Position basse, cuisses à l’horizontale.' },
  'v-squat': { d: 'Dans une machine V-squat, épaules sous les appuis. Genoux fléchis à 90°.' },
  'goblet': { d: 'Un haltère tenu verticalement contre la poitrine. Position basse, coudes entre les genoux, buste droit.' },
  'zercher': { d: 'Barre tenue dans le creux des coudes devant le ventre. Position basse du squat.' },
  'squat-landmine': { d: 'Bout d’une barre landmine tenu à deux mains devant la poitrine. Position basse du squat.' },
  'squat-pdc': { d: 'Sans charge, bras tendus devant. Position basse : cuisses à l’horizontale, dos plat.' },
  'squat-saute': { d: 'En l’air au milieu d’un saut, après un squat, bras le long du corps, jambes tendues.' },
  'pistol': { d: 'Squat sur une jambe, l’autre jambe tendue devant à l’horizontale, bras devant. Position basse.' },
  'bulgare': { d: 'Pied arrière posé sur un banc, un haltère dans chaque main. Descente : genou arrière près du sol, tibia avant presque vertical.' },
  'bulgare-smith': { d: 'Fente bulgare sous une barre guidée (Smith), pied arrière sur un banc. Genou arrière près du sol.' },
  'bulgare-pdc': { d: 'Fente bulgare sans charge, pied arrière sur un banc, mains sur les hanches. Genou arrière près du sol.' },
  'fentes-avant': { d: 'Grand pas en avant, un haltère dans chaque main. Genou arrière près du sol, les deux genoux à 90°.' },
  'fentes-arriere': { d: 'Pas en arrière, un haltère dans chaque main. Genou arrière près du sol, buste droit.' },
  'fentes-marchees': { d: 'Fente en marchant, un haltère dans chaque main. Genou arrière près du sol, en avançant.' },
  'fentes-barre': { d: 'Barre sur le haut du dos. Fente : genou arrière près du sol.' },
  'fentes-smith': { d: 'Fente sous une barre guidée (Smith). Genou arrière près du sol.' },
  'fentes-pdc': { d: 'Fente sans charge, mains sur les hanches. Genou arrière près du sol.' },
  'split-squat': { d: 'Fente statique, pieds fixes, un haltère dans chaque main. Genou arrière près du sol.' },
  'step-up': { d: 'Un pied posé sur un banc, un haltère dans chaque main. Montée sur le banc, jambe d’appui presque tendue.' },
  'leg-ext': { d: 'Assis dans une machine leg extension, chevilles sous le boudin. Jambes tendues devant.' },
  'leg-ext-1': { d: 'Assis dans une machine leg extension, une seule jambe tendue devant, l’autre au repos.' },
  'sissy': { d: 'Debout sur la pointe des pieds, genoux poussés loin vers l’avant, buste incliné en arrière dans l’alignement des cuisses, une main tient un support.' },
  'chaise': { d: 'Dos contre un mur, cuisses à l’horizontale, genoux à 90°, bras le long du corps.' },
  'spanish-squat': { d: 'Un élastique épais derrière les genoux, fixé devant à un support solide. Position basse, tibias verticaux, buste droit.' },

  // ---------- Ischios ----------
  'rdl': { d: 'Debout, barre devant les cuisses. Hanches poussées en arrière, buste penché, barre sous les genoux, dos plat, genoux légèrement fléchis.' },
  'rdl-halteres': { d: 'Un haltère dans chaque main devant les cuisses. Hanches en arrière, haltères à mi-tibias, dos plat.' },
  'rdl-1jambe': { d: 'Sur une jambe, l’autre tendue vers l’arrière à l’horizontale, buste à l’horizontale, haltère dans la main opposée à la jambe d’appui.' },
  'sldl': { d: 'Jambes presque tendues, barre descendue près des pieds, dos plat.' },
  'good-morning': { d: 'Barre sur le haut du dos. Buste penché vers l’avant jusqu’à l’horizontale, dos plat, genoux légèrement fléchis.' },
  'leg-curl-allonge': { d: 'Allongé sur le ventre dans une machine leg curl, chevilles sous le boudin. Talons ramenés vers les fesses.' },
  'leg-curl-assis': { d: 'Assis dans une machine leg curl, jambes sur le boudin. Talons ramenés sous le siège.' },
  'leg-curl-debout': { d: 'Debout dans une machine leg curl, une jambe. Talon ramené vers la fesse.' },
  'leg-curl-poulie': { d: 'Debout face à une poulie basse, sangle à la cheville. Talon ramené vers la fesse.' },
