  'ghr': { d: 'Sur une machine glute-ham, genoux sur le coussin, pieds calés. Corps qui remonte de l’horizontale vers la verticale en pliant les genoux.' },

  // ---------- Fessiers ----------
  'hip-thrust': { d: 'Haut du dos posé sur un banc, barre sur les hanches, pieds au sol. Hanches poussées en haut : corps à l’horizontale des genoux aux épaules.' },
